def query_segment(tree, node, start, end, l, r):
    if l > end or r < start:
        return float('inf')
    if l <= start and end <= r:
        return tree[node]
    mid = (start + end) // 2
    left = query_segment(tree, 2*node, start, mid, l, r)
    right = query_segment(tree, 2*node+1, mid+1, end, l, r)
    return min(left, right)
