        self.n = len(arr)
        self.t = [0]*(4*self.n)
        self.build(arr, 1, 0, self.n-1)
    def build(self, arr, v, tl, tr):
        if tl == tr:
            self.t[v] = arr[tl]
        else:
            tm = (tl+tr)//2
            self.build(arr, v*2, tl, tm)
            self.build(arr, v*2+1, tm+1, tr)
            self.t[v] = self.t[v*2] ^ self.t[v*2+1]
    def query(self, v, tl, tr, l, r):
        if l > r: return 0
        if l == tl and r == tr: return self.t[v]
        tm = (tl+tr)//2
        return self.query(v*2, tl, tm, l, min(r, tm)) ^ self.query(v*2+1, tm+1, tr, max(l, tm+1), r)
