                for j in range(self.m - (1<<k) + 1):
                    self.st[0][i][j][k] = min(self.st[0][i][j][k-1], self.st[0][i][j+(1<<(k-1))][k-1])
        for ki in range(1, self.logn):
            for i in range(self.n - (1<<ki) + 1):
                for kj in range(self.logm):
                    for j in range(self.m):
                        if j + (1<<kj) <= self.m:
                            self.st[ki][i][j][kj] = min(self.st[ki-1][i][j][kj], self.st[ki-1][i+(1<<(ki-1))][j][kj])
    def qry(self, x1, y1, x2, y2):
        ki = (x2 - x1 + 1).bit_length() - 1
        kj = (y2 - y1 + 1).bit_length() - 1
        a = self.st[ki][x1][y1][kj]
        b = self.st[ki][x1][y2-(1<<kj)+1][kj]
        c = self.st[ki][x2-(1<<ki)+1][y1][kj]
        d = self.st[ki][x2-(1<<ki)+1][y2-(1<<kj)+1][kj]
        return min(a,b,c,d)
mat = [[1, 2, 3], [4, 5, 6], [7, 8, 9]]
st = SparseTable2D(mat)
