class BITRangeAdd:
    def __init__(self, n):
        self.n = n
        self.B1 = [0]*(n+2)
        self.B2 = [0]*(n+2)
    def _add(self, b, i, v):
        while i <= self.n:
            b[i] += v
            i += i & -i
    def radd(self, l, r, v):
        self._add(self.B1, l, v)
        self._add(self.B1, r+1, -v)
        self._add(self.B2, l, v*(l-1))
        self._add(self.B2, r+1, -v*r)
    def psum(self, i):
        def q(b, x):
            s = 0
            while x: s += b[x]; x -= x & -x
            return s
        return q(self.B1, i)*i - q(self.B2, i)
    def rsum(self, l, r):
        return self.psum(r) - self.psum(l-1)
bit = BITRangeAdd(20)
for i in range(1, 11):
    bit.radd(i, i+5, i)
print(bit.rsum(5, 10))

class SegTree2D:
    def __init__(self, mat):
        self.n, self.m = len(mat), len(mat[0])
        self.t = [[0]*(4*self.m) for _ in range(4*self.n)]
        self.build_y(1, 0, 0, self.n-1, mat)
    def build_y(self, vx, vy, tl, tr, mat):
        if tl == tr:
            self.build_x(vx, vy, tl, 0, self.m-1, mat)
        else:
            tm = (tl+tr)//2
            self.build_y(vx, vy*2, tl, tm, mat)
            self.build_y(vx, vy*2+1, tm+1, tr, mat)
            for i in range(4*self.m):
                self.t[vx][i] = self.t[vy*2][i] + self.t[vy*2+1][i]
    def build_x(self, vx, vy, row, l, r, mat):
        if l == r:
            self.t[vy][vx] = mat[row][l]
        else:
            m = (l+r)//2
            self.build_x(vx*2, vy, row, l, m, mat)
            self.build_x(vx*2+1, vy, row, m+1, r, mat)
            self.t[vy][vx] = self.t[vy][vx*2] + self.t[vy][vx*2+1]
