class Fenwick2D:
    def __init__(self, n, m):
        self.n, self.m = n, m
        self.t = [[0]*(m+1) for _ in range(n+1)]
    def upd(self, x, y, v):
        i = x
        while i <= self.n:
            j = y
            while j <= self.m:
                self.t[i][j] += v
                j += j & -j
            i += i & -i
    def qry(self, x, y):
        s = 0
        i = x
        while i:
            j = y
            while j:
                s += self.t[i][j]
                j -= j & -j
            i -= i & -i
        return s
    def rsum(self, x1, y1, x2, y2):
        return self.qry(x2, y2) - self.qry(x1-1, y2) - self.qry(x2, y1-1) + self.qry(x1-1, y1-1)
bit = Fenwick2D(4, 4)
for i in range(1, 5):
    for j in range(1, 5):
        bit.upd(i, j, i*2 + j)
print(bit.rsum(2, 2, 3, 4))

class SparseTable:
    def __init__(self, arr):
        self.n = len(arr)
        self.k = self.n.bit_length()
        self.st = [[0]*self.k for _ in range(self.n)]
        self.log = [0]*(self.n+1)
        for i in range(2, self.n+1):
            self.log[i] = self.log[i//2] + 1
        for i in range(self.n):
            self.st[i][0] = arr[i]
        for j in range(1, self.k):
            for i in range(self.n - (1<<j) + 1):
                self.st[i][j] = self.st[i][j-1] & self.st[i+(1<<(j-1))][j-1]
    def qry(self, l, r):
        j = self.log[r-l+1]
        return self.st[l][j] & self.st[r-(1<<j)+1][j]
st = SparseTable([7, 6, 5, 3, 1])
print(st.qry(1, 3))
